        header=r'''struct CrcFrame{std::uint16_t type;std::vector<std::uint8_t> payload;};class CrcRecoveryFrameStore{public:explicit CrcRecoveryFrameStore(std::size_t);bool write(std::uint16_t,std::vector<std::uint8_t>);std::optional<CrcFrame> read();bool corrupt_head(std::size_t);bool inject_incomplete(std::uint16_t,std::vector<std::uint8_t>,std::size_t);std::size_t corrupt_count()const;private:std::size_t cap_;std::deque<std::uint8_t> bytes_;std::size_t corrupt_=0;static std::uint16_t checksum(std::uint16_t,const std::vector<std::uint8_t>&);};''',
        reference=r'''std::uint16_t CrcRecoveryFrameStore::checksum(std::uint16_t type,const std::vector<std::uint8_t>&p){std::uint32_t c=type;for(auto b:p)c=(c*257u+b)&0xffffu;return static_cast<std::uint16_t>(c);}CrcRecoveryFrameStore::CrcRecoveryFrameStore(std::size_t n):cap_(n){if(!n)throw std::invalid_argument("capacity");}bool CrcRecoveryFrameStore::write(std::uint16_t type,std::vector<std::uint8_t> p){if(p.empty()||p.size()>std::numeric_limits<std::uint16_t>::max())return false;std::size_t n=p.size()+6;if(n>cap_-bytes_.size())return false;auto crc=checksum(type,p);bytes_.push_back(static_cast<std::uint8_t>(type&0xff));bytes_.push_back(static_cast<std::uint8_t>(type>>8));bytes_.push_back(static_cast<std::uint8_t>(p.size()&0xff));bytes_.push_back(static_cast<std::uint8_t>(p.size()>>8));bytes_.push_back(static_cast<std::uint8_t>(crc&0xff));bytes_.push_back(static_cast<std::uint8_t>(crc>>8));for(auto b:p)bytes_.push_back(b);return true;}std::optional<CrcFrame> CrcRecoveryFrameStore::read(){while(bytes_.size()>=6){std::uint16_t type=static_cast<std::uint16_t>(bytes_[0]|(std::uint16_t(bytes_[1])<<8));std::size_t len=static_cast<std::size_t>(bytes_[2]|(std::uint16_t(bytes_[3])<<8));if(len+6>bytes_.size())return std::nullopt;std::uint16_t stored=static_cast<std::uint16_t>(bytes_[4]|(std::uint16_t(bytes_[5])<<8));std::vector<std::uint8_t> payload;for(std::size_t i=0;i<len;++i)payload.push_back(bytes_[6+i]);for(std::size_t i=0;i<len+6;++i)bytes_.pop_front();if(checksum(type,payload)!=stored){++corrupt_;continue;}return CrcFrame{type,std::move(payload)};}return std::nullopt;}bool CrcRecoveryFrameStore::corrupt_head(std::size_t i){if(bytes_.size()<6)return false;std::size_t len=static_cast<std::size_t>(bytes_[2]|(std::uint16_t(bytes_[3])<<8));if(i>=len||6+i>=bytes_.size())return false;bytes_[6+i]^=0x5a;return true;}bool CrcRecoveryFrameStore::inject_incomplete(std::uint16_t type,std::vector<std::uint8_t> p,std::size_t prefix){if(p.empty()||p.size()>std::numeric_limits<std::uint16_t>::max())return false;std::vector<std::uint8_t> raw{static_cast<std::uint8_t>(type&0xff),static_cast<std::uint8_t>(type>>8),static_cast<std::uint8_t>(p.size()&0xff),static_cast<std::uint8_t>(p.size()>>8),0,0};raw.insert(raw.end(),p.begin(),p.end());prefix=std::min(prefix,raw.size());if(prefix>cap_-bytes_.size())return false;for(std::size_t i=0;i<prefix;++i)bytes_.push_back(raw[i]);return true;}std::size_t CrcRecoveryFrameStore::corrupt_count()const{return corrupt_;}''',
        visible=r'''int main(){CrcRecoveryFrameStore s(24);CHECK(s.write(1,{2,3}));CHECK(s.write(4,{5}));CHECK(s.corrupt_head(0));auto f=s.read();CHECK(f&&f->type==4&&f->payload==std::vector<std::uint8_t>({5}));CHECK(s.corrupt_count()==1);return failures;}''',
