        reference=r'''SegmentedDeltaSamples::SegmentedDeltaSamples(std::size_t n):cap_(n){if(!n)throw std::invalid_argument("capacity");}void SegmentedDeltaSamples::rebuild(const std::vector<std::int64_t>&values){cells_.clear();for(std::size_t i=0;i<values.size();++i){bool base=true;std::int64_t encoded=values[i];if(i){auto prev=values[i-1];bool overflow=(values[i]>0&&prev<std::numeric_limits<std::int64_t>::min()+values[i])||(values[i]<0&&prev>std::numeric_limits<std::int64_t>::max()+values[i]);if(overflow)throw std::overflow_error("delta");auto delta=values[i]-prev;if(delta>=-32768&&delta<=32767){base=false;encoded=delta;}}cells_.push_back({base,encoded});}}bool SegmentedDeltaSamples::append(std::int64_t v){auto values=decode();if(!values.empty()){auto prev=values.back();if((v>0&&prev<std::numeric_limits<std::int64_t>::min()+v)||(v<0&&prev>std::numeric_limits<std::int64_t>::max()+v))throw std::overflow_error("delta");}values.push_back(v);if(values.size()>cap_)values.erase(values.begin());rebuild(values);return true;}std::vector<std::int64_t> SegmentedDeltaSamples::decode()const{std::vector<std::int64_t> out;for(const auto&c:cells_){if(c.base||out.empty())out.push_back(c.value);else out.push_back(out.back()+c.value);}return out;}std::optional<std::int64_t> SegmentedDeltaSamples::at(std::size_t age)const{auto v=decode();return age<v.size()?std::optional<std::int64_t>(v[v.size()-1-age]):std::nullopt;}std::size_t SegmentedDeltaSamples::base_segments()const{return static_cast<std::size_t>(std::count_if(cells_.begin(),cells_.end(),[](auto&c){return c.base;}));}''',
